const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=d=>d.tokens.map(t=>t.text).join(d.lang==='zh'?'':' ');
let saved={favorites:[],done:[]};try{saved={...saved,...JSON.parse(localStorage.getItem('elo-progress')||'{}')};if(!Array.isArray(saved.favorites)||!Array.isArray(saved.done))throw Error();}catch{saved={favorites:[],done:[]};}
let lang='en',view='explorer',level='all',selected=D[0].id,rate=.8,voiceName='',repeat=false,speechRun=0,voices=[],practiceId=selected,answerOrder=[],chosen=[],recorder=null,recordStream=null,recordUrl=null,recordTimer;
function persist(){try{localStorage.setItem('elo-progress',JSON.stringify(saved))}catch{toast('Não foi possível salvar neste navegador.')}updateCount()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function updateCount(){$('#studied-count').textContent=saved.done.length+' estudo'+(saved.done.length===1?'':'s')}
function current(){return D.find(d=>d.id===selected)}
