function fillFilters(){const data=D.filter(d=>d.lang===lang);$('#topic').innerHTML='<option value="">Todos os assuntos</option>'+[...new Set(data.map(d=>d.topic))].map(t=>`<option>${esc(t)}</option>`).join('');$('#feature').innerHTML='<option value="">Todos os fenômenos</option>'+[...new Set(data.flatMap(d=>d.features))].map(t=>`<option>${esc(t)}</option>`).join('')}
function setLang(l){if(!['en','zh'].includes(l))throw Error('Idioma inválido');stopAudio();stopRecording();lang=l;selected=D.find(d=>d.lang===l).id;practiceId=selected;voiceName='';$('#search').value='';fillFilters();['en','zh'].forEach(x=>{$('#'+x).classList.toggle('selected',x===lang);$('#'+x).setAttribute('aria-pressed',String(x===lang))});renderAll()}
function setView(v){if(!['explorer','atlas','practice','review'].includes(v))return;stopAudio();stopRecording();view=v;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));['explorer','atlas','practice','review'].forEach(x=>$('#'+x+'-view').hidden=x!==v);const titles={explorer:['Explorar frases','A frase, por dentro.','Da palavra escrita ao jeito de falar.'],atlas:['Atlas gramatical','Cada palavra tem um papel.','Uma referência para entender e combinar.'],practice:['Praticar','Agora, a sua vez.','Reconheça a estrutura. Monte a frase. Diga em voz alta.'],review:['Minha revisão','Faça as conexões ficarem.','Seus favoritos e estudos neste dispositivo.']};$('#view-title').textContent=titles[v][0];$('#page-title').textContent=titles[v][1];$('#page-subtitle').textContent=titles[v][2];renderAll()}
function renderAll(){updateCount();if(view==='explorer')renderList();if(view==='atlas')renderAtlas();if(view==='practice')renderPractice();if(view==='review')renderReview()}
function renderList(){const data=matches();$('#result-count').textContent=data.length+' estudos encontrados';if(data.length&&!data.some(d=>d.id===selected)){stopAudio();selected=data[0].id}$('#results').innerHTML=data.length?data.map(d=>`<button class="result ${d.id===selected?'active':''}" data-id="${d.id}" aria-pressed="${d.id===selected}"><div class="meta"><span class="level-pill">${d.level}</span>${esc(d.topic)}${saved.done.includes(d.id)?' · ✓':''}</div><strong>${esc(plain(d))}</strong><small>${esc(d.title)}</small></button>`).join(''):'<div class="empty">Nenhuma frase encontrada. Experimente outro filtro.</div>';$$('.result').forEach(b=>b.onclick=()=>{stopAudio();selected=b.dataset.id;renderList()});if(data.length)renderLesson();else $('#lesson').innerHTML='<div class="empty"><strong>Vamos ampliar a busca?</strong><p>Remova um filtro ou escolha outro nível.</p><button class="secondary-button" id="clear-filters">Limpar filtros</button></div>';if($('#clear-filters'))$('#clear-filters').onclick=resetFilters}
function resetFilters(){level='all';$('#search').value='';$('#topic').value='';$('#feature').value='';$$('[data-level]').forEach(b=>b.classList.toggle('selected',b.dataset.level==='all'));renderList()}
function tokenMarkup(d){return d.tokens.map((t,i)=>`<button class="token" style="--token-color:${CLASSES[t.c][1]}" data-word="${i}" aria-label="${esc(t.text)}, ${CLASSES[t.c][0]}">${esc(t.text)}</button>`).join('')}
function renderLesson(){const d=current();const fav=saved.favorites.includes(d.id);$('#lesson').innerHTML=`<article class="lesson-card"><div class="lesson-top"><div class="meta"><span class="level-pill">${d.level}</span><span>${esc(d.topic)}</span><span>•</span><span>${d.lang==='en'?'English':'普通话'}</span></div><button class="icon-btn ${fav?'saved':''}" id="favorite" aria-label="${fav?'Remover dos':'Adicionar aos'} favoritos" aria-pressed="${fav}">${fav?'★':'☆'}</button></div><div class="sentence-area"><div class="tokens" lang="${d.lang==='en'?'en':'zh-CN'}">${tokenMarkup(d)}</div><p class="translation">${esc(d.translation)}</p><p class="literal">Estrutura literal · ${esc(d.literal)}</p><div class="legend">${[...new Set(d.tokens.map(t=>t.c))].map(c=>`<span><i style="background:${CLASSES[c][1]}"></i>${CLASSES[c][0]}</span>`).join('')}</div></div><section class="natural"><div class="natural-head"><strong>${d.lang==='en'?'É ASSIM QUE SE CONECTA':'SONS, TONS E CONEXÕES'}</strong><span class="accent-label">${d.lang==='en'?(d.features.includes('Glottalization')?'VARIANTE BRITÂNICA':'REFERÊNCIA AMERICANA'):'MANDARIM PADRÃO'}</span></div><p class="phonetic">${esc(d.phonetic)}</p><p class="notation">${esc(d.notation)}</p><p class="approx-note">${d.lang==='en'?'Aproximação brasileira · MAIÚSCULAS = destaque · ɾ = r de caro · ʔ = parada glotal':'Aproximação brasileira · ↗ sobe · ↘ desce · ̄ alto · · neutro · pinyin é a referência'}</p><div class="playbar"><button class="play-button" id="play-natural">▶ Ouvir frase</button><button class="secondary-button" id="stop">■ Parar</button><label class="speed">Velocidade <select id="rate">${[.5,.65,.8,1,1.2].map(r=>`<option value="${r}" ${rate===r?'selected':''}>${String(r).replace('.',',')}×</option>`).join('')}</select></label></div><p class="audio-status" id="audio-status" aria-live="polite">Voz sintética do dispositivo · realização pode variar.</p></section><details class="audio-settings"><summary>Voz, repetição e limites do áudio</summary><p>O áudio é uma leitura sintética. Não é gravação humana nem garante as reduções descritas. A velocidade ajusta a síntese; não desacelera uma gravação original.</p><label for="voice">Voz disponível</label><select id="voice"></select><label><input id="repeat" type="checkbox" ${repeat?'checked':''}> Repetir a frase, com 2 segundos para acompanhar</label><button class="secondary-button" id="play-full">Ouvir escrita completa</button><p>Algumas vozes exigem internet. Sem voz deste idioma, o app informa a limitação em vez de ler com outro idioma.</p></details><div class="lesson-details"><h2 class="subheading"><span>≋</span> ${d.lang==='en'?'DA ESCRITA À FALA':'COMO A FRASE FUNCIONA'}</h2><div class="steps">${d.steps.map((s,i)=>`<div class="step"><span class="step-num">${i+1}</span>${esc(s)}</div>`).join('')}</div><div class="features">${d.features.map(f=>`<span class="feature">${esc(f)}</span>`).join('')}</div><p class="explanation">${esc(d.note)}</p><h2 class="subheading"><span>▥</span> OS BLOCOS DA FRASE</h2><div class="blocks">${d.structure.map(s=>{const parts=s.split(' · ');return `<div class="block"><small>${esc(parts[1]||'estrutura')}</small>${esc(parts[0])}</div>`}).join('')}</div><div class="lesson-actions"><small>Toque em uma palavra<br>para explorar sua classe.</small><button class="primary-button" id="practice-this">Praticar esta frase</button></div></div></article>`;$('#favorite').onclick=()=>{saved.favorites=fav?saved.favorites.filter(x=>x!==d.id):[...saved.favorites,d.id];persist();renderLesson()};$$('[data-word]').forEach(b=>b.onclick=()=>showWord(d,+b.dataset.word));$('#rate').onchange=e=>{rate=+e.target.value;stopAudio()};$('#play-natural').onclick=()=>speak(d.natural,d.lang);$('#play-full').onclick=()=>speak(plain(d),d.lang);$('#stop').onclick=stopAudio;$('#repeat').onchange=e=>{repeat=e.target.checked;if(!repeat)stopAudio()};$('#practice-this').onclick=()=>{practiceId=d.id;setView('practice')};populateVoices()}
function populateVoices(){if(!('speechSynthesis'in window))return;if(!$('#voice'))return;voices=speechSynthesis.getVoices();const allowed=voices.filter(v=>lang==='en'?v.lang.toLowerCase().startsWith('en'): /^(zh|cmn)(-|_|$)/i.test(v.lang)&&!/(HK|TW|yue)/i.test(v.lang));$('#voice').innerHTML=allowed.length?allowed.map(v=>`<option value="${esc(v.name)}" ${voiceName===v.name?'selected':''}>${esc(v.name)} · ${esc(v.lang)}${v.localService?' · local':''}</option>`).join(''):'<option value="">Nenhuma voz encontrada para este idioma</option>';if(!voiceName&&allowed.length){const preferred=allowed.find(v=>lang==='en'?v.lang==='en-US':/CN/i.test(v.lang))||allowed[0];$('#voice').value=preferred.name;voiceName=preferred.name}$('#voice').onchange=e=>{voiceName=e.target.value;stopAudio()}}
function audioStatus(t){if($('#audio-status'))$('#audio-status').textContent=t;else toast(t)}
function stopAudio(){speechRun++;if('speechSynthesis'in window)speechSynthesis.cancel();if($('#play-natural'))$('#play-natural').textContent='▶ Ouvir frase'}
function speak(text,l,once=false){stopAudio();if(!('speechSynthesis'in window)){audioStatus('Este navegador não oferece síntese de voz.');return}voices=speechSynthesis.getVoices();const available=voices.filter(v=>l==='en'?/^en/i.test(v.lang):/^(zh|cmn)(-|_|$)/i.test(v.lang)&&!/(HK|TW|yue)/i.test(v.lang));let chosenVoice=available.find(v=>v.name===voiceName)||available.find(v=>l==='en'?v.lang==='en-US':/CN/i.test(v.lang))||available[0];if(!chosenVoice){audioStatus('Nenhuma voz de '+(l==='en'?'inglês':'mandarim')+' disponível. Ative esse idioma nas configurações de voz do dispositivo.');toast('Não há voz disponível para este idioma neste navegador.');return}const run=speechRun;const play=()=>{if(run!==speechRun)return;const u=new SpeechSynthesisUtterance(text);u.lang=chosenVoice.lang;u.voice=chosenVoice;u.rate=rate;u.onstart=()=>{audioStatus('Reproduzindo · '+chosenVoice.name+' · '+rate+'×');if($('#play-natural'))$('#play-natural').textContent='♫ Reproduzindo'};u.onend=()=>{if(run!==speechRun)return;audioStatus('Concluído · tente repetir em voz alta.');if($('#play-natural'))$('#play-natural').textContent='▶ Ouvir frase';if(repeat&&!once)setTimeout(play,2000)};u.onerror=e=>{if(e.error==='canceled'||e.error==='interrupted')return;audioStatus('Não foi possível reproduzir. Tente outra voz ou verifique a conexão.');if($('#play-natural'))$('#play-natural').textContent='▶ Ouvir frase'};speechSynthesis.speak(u)};play()}
function showWord(d,i){const t=d.tokens[i],c=CLASSES[t.c];$('#word-content').innerHTML=`<p class="eyebrow" style="color:${c[1]}">${c[0].toUpperCase()}</p><h2 style="color:${c[1]}">${esc(t.text)}</h2><p><strong>Nesta frase:</strong> ${esc(t.gloss)}</p><p>${c[2]}</p><p class="literal">${esc(d.translation)}</p><button class="primary-button" id="word-audio">▶ Ouvir palavra</button><p class="literal" style="margin-top:14px">A pronúncia isolada pode diferir da palavra dentro da frase.</p>`;$('#word-audio').onclick=()=>speak(t.text,d.lang,true);$('#word-modal').showModal()}
$('.close').onclick=()=>{$('#word-modal').close();stopAudio()};$('#word-modal').addEventListener('click',e=>{if(e.target===$('#word-modal'))$('#word-modal').close()});
const ATLAS={en:{n:['sample · amostra','Pode ser sujeito ou objeto. Nomes contáveis podem variar em número: sample / samples.'],v:['have been approved','Auxiliares ajudam a marcar tempo, aspecto, modalidade e voz. Identifique o grupo inteiro.'],adj:['a large sample','Em geral precede o nome ou aparece após um verbo de ligação. Ordem de adjetivos depende de significado e contexto.'],adv:['already · carefully','Pode indicar tempo, modo, intensidade ou posição do falante. Nem todo advérbio termina em -ly.'],pro:['I · you · me','A forma depende da função: I como sujeito, me como objeto.'],det:['the · an · my','Artigos e possessivos ajudam a identificar qual nome está em foco. An depende do som seguinte.'],prep:['in · on · by','Aprenda também a combinação inteira: interested in, depend on. By pode introduzir o agente da passiva.'],conj:['if · although · and','Observe a relação: condição, concessão, adição. Conectar orações não é apenas traduzir uma palavra.'],num:['two samples','Numerais podem indicar quantidade ou ordem: two / second.'],part:['to go · look up','To pode marcar infinitivo. Em look up, up funciona como partícula; a análise depende da construção.']},zh:{n:['样品 · amostra','Nomes não recebem uma terminação geral de plural como em português. 今天 é um nome temporal com função adverbial.'],v:['学习 · estudar','O verbo não se conjuga por pessoa como em português. Tempo e aspecto são expressos pelo contexto e por outros elementos.'],adj:['好 · bom','Adjetivos podem funcionar como predicados. Não insira 是 automaticamente em toda descrição.'],adv:['已经 · já','Frequentemente aparece antes do verbo. 不 e 没 têm usos diferentes de negação.'],pro:['我 · 你 · 我们','我 = eu; 我们 = nós. 的 pode ligar o possuidor ao que é possuído.'],prep:['在家 · em casa','Grupos como 在家 frequentemente aparecem antes do verbo principal. Algumas palavras têm análise diferente conforme o uso.'],conj:['虽然…但是…','Conectores podem trabalhar em pares. Traduza o sentido da relação, sem copiar obrigatoriamente cada conector.'],num:['一 · 二 · 三','Antes de um nome contado, normalmente aparece também um classificador. 一 pode mudar de tom.'],clf:['一杯咖啡','Numeral + classificador + nome. 杯 serve para copos/xícaras; 个 é comum, mas não serve em todos os contextos.'],part:['的 · 了 · 过','的 pode marcar modificação ou posse; 了 e 过 têm usos de aspecto. Não equivalem simplesmente a tempos verbais portugueses.']}};
function renderAtlas(){$('#atlas-grid').innerHTML=Object.entries(ATLAS[lang]).map(([c,a])=>`<article class="atlas-card" style="--token-color:${CLASSES[c][1]}"><h2>${CLASSES[c][0]}</h2><p>${CLASSES[c][2]}</p><p class="example">${a[0]}</p><p>${a[1]}</p><button class="secondary-button" data-class="${c}">Explorar exemplo</button></article>`).join('');$$('[data-class]').forEach(b=>b.onclick=()=>{let d=D.find(d=>d.lang===lang&&d.tokens.some(t=>t.c===b.dataset.class));if(d){resetFilters();selected=d.id;setView('explorer')}else toast('Esta classe terá mais exemplos na expansão do acervo.')})}
function shuffle(a){return a.map(x=>({x,r:Math.random()})).sort((a,b)=>a.r-b.r).map(a=>a.x)}
function renderPractice(){stopRecording();let d=D.find(d=>d.id===practiceId&&d.lang===lang)||D.find(d=>d.lang===lang);practiceId=d.id;chosen=[];answerOrder=shuffle(d.tokens.map((t,i)=>i));$('#practice').innerHTML=`<div class="practice-card"><div class="meta"><span class="level-pill">${d.level}</span>${esc(d.topic)} · ${esc(d.title)}</div><h2>Entenda primeiro. Depois, reconstrua.</h2><p class="prompt">${esc(plain(d))}</p><p class="translation">${esc(d.translation)}</p><p>${esc(d.quiz[0])}</p><div class="options">${shuffle(d.quiz.slice(1,4).map((a,i)=>({a,correct:i===0}))).map(o=>`<button class="option" data-correct="${o.correct}">${esc(o.a)}</button>`).join('')}</div><p id="quiz-feedback" class="feedback" aria-live="polite"></p><h3>Monte a frase original</h3><p class="literal">Toque nos blocos na ordem. Toque em um bloco escolhido para devolvê-lo.</p><div class="order-tray" id="chosen"></div><div class="order-tray" id="bank"></div><button id="check-order" class="primary-button">Conferir ordem</button><p class="feedback" id="order-feedback" aria-live="polite"></p><h3>Ouça e repita</h3><p class="phonetic">${esc(d.phonetic)}</p><p class="literal">${esc(d.notation)}</p><div class="record-row"><button id="practice-audio" class="secondary-button">▶ Ouvir a ${rate}×</button><button id="record" class="secondary-button">● Gravar minha voz</button><audio id="recording" controls hidden></audio></div><p class="literal" id="record-status" aria-live="polite">Gravação local e temporária, até 60 segundos. Sem envio e sem nota automática.</p><div class="lesson-actions"><button id="back-lesson" class="secondary-button">Rever explicação</button><button id="next-practice" class="primary-button">Próximo estudo</button></div></div>`;$$('.option').forEach(b=>b.onclick=()=>{const ok=b.dataset.correct==='true';b.classList.add(ok?'correct':'wrong');$('#quiz-feedback').textContent=(ok?'Correto. ':'Ainda não. ')+d.quiz[4];if(ok){$$('.option').forEach(x=>x.disabled=true);markDone(d.id)}});renderOrder(d);$('#check-order').onclick=()=>{const actual=chosen.map(i=>d.tokens[i].text).join('|'),expected=d.tokens.map(t=>t.text).join('|');const ok=actual===expected;$('#order-feedback').textContent=ok?'Ordem correta. '+d.literal:'Ainda não é a ordem da frase original. Observe os blocos na explicação e tente novamente.';if(ok)markDone(d.id)};$('#practice-audio').onclick=()=>speak(d.natural,d.lang,true);$('#record').onclick=record;$('#back-lesson').onclick=()=>{selected=d.id;resetFilters();selected=d.id;setView('explorer')};$('#next-practice').onclick=()=>{stopAudio();const list=D.filter(x=>x.lang===lang);practiceId=list[(list.findIndex(x=>x.id===d.id)+1)%list.length].id;renderPractice()}}
function renderOrder(d){$('#chosen').innerHTML=chosen.length?chosen.map((i,pos)=>`<button class="order-token" data-pos="${pos}">${esc(d.tokens[i].text)}</button>`).join(''):'<span class="literal">Sua frase aparece aqui…</span>';$('#bank').innerHTML=answerOrder.filter(i=>!chosen.includes(i)).map(i=>`<button class="order-token" data-index="${i}">${esc(d.tokens[i].text)}</button>`).join('');$$('[data-index]').forEach(b=>b.onclick=()=>{chosen.push(+b.dataset.index);renderOrder(d)});$$('[data-pos]').forEach(b=>b.onclick=()=>{chosen.splice(+b.dataset.pos,1);renderOrder(d)})}
function markDone(id){if(!saved.done.includes(id)){saved.done.push(id);persist()}}
function stopRecording(){clearTimeout(recordTimer);if(recorder&&recorder.state==='recording')recorder.stop();if(recordStream){recordStream.getTracks().forEach(t=>t.stop());recordStream=null}}
async function record(){if(recorder&&recorder.state==='recording'){stopRecording();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Gravação indisponível neste navegador.');return}try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});if(view!=='practice'){stopRecording();return}const chunks=[];recorder=new MediaRecorder(recordStream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType||'audio/webm'}));if($('#recording')&&view==='practice'){$('#recording').src=recordUrl;$('#recording').hidden=false;$('#record').textContent='● Gravar novamente';$('#record-status').textContent='Ouça e compare ritmo, sons e pausas. O áudio fica apenas nesta sessão.'}if(recordStream)recordStream.getTracks().forEach(t=>t.stop())};recorder.start();$('#record').textContent='■ Encerrar gravação';$('#record-status').textContent='Gravando… encerre quando terminar (máximo de 60 segundos).';recordTimer=setTimeout(stopRecording,60000)}catch{stopRecording();toast('Não foi possível acessar o microfone. Verifique a permissão do navegador.')}}
function renderReview(){const data=D.filter(d=>d.lang===lang&&(saved.favorites.includes(d.id)||saved.done.includes(d.id)));$('#review').innerHTML=data.length?'<div class="review-grid">'+data.map(d=>`<article class="review-card"><div class="meta"><span class="level-pill">${d.level}</span>${saved.favorites.includes(d.id)?'★ Favorito':''} ${saved.done.includes(d.id)?'✓ Praticado':''}</div><h3>${esc(plain(d))}</h3><p>${esc(d.translation)}</p><button class="secondary-button" data-review="${d.id}">Revisar frase</button></article>`).join('')+'</div>':'<div class="empty"><strong>Suas conexões começam aqui.</strong><p>Favorite uma frase com ☆ ou complete um exercício para encontrá-lo nesta seção.</p><button id="start-review" class="primary-button">Explorar frases</button></div>';$$('[data-review]').forEach(b=>b.onclick=()=>{resetFilters();selected=b.dataset.review;setView('explorer')});if($('#start-review'))$('#start-review').onclick=()=>setView('explorer')}
$$('.nav').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#en').onclick=()=>setLang('en');$('#zh').onclick=()=>setLang('zh');$('#search').oninput=renderList;$('#topic').onchange=renderList;$('#feature').onchange=renderList;$$('[data-level]').forEach(b=>b.onclick=()=>{level=b.dataset.level;$$('[data-level]').forEach(x=>x.classList.toggle('selected',x===b));renderList()});if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',populateVoices);window.addEventListener('pagehide',()=>{stopAudio();stopRecording()});fillFilters();renderAll();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'explore_language_phrase',title:'Explorar frase no Elo',description:'Seleciona um idioma e uma frase disponível no explorador, sem alterar o progresso.',inputSchema:{type:'object',properties:{phraseId:{type:'string'}},required:['phraseId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.phraseId!=='string')throw Error('Informe phraseId.');const d=D.find(d=>d.id===input.phraseId);if(!d)throw Error('Frase inexistente.');setLang(d.lang);resetFilters();selected=d.id;setView('explorer');return {id:d.id,phrase:plain(d),translation:d.translation}}})).catch(()=>{})}catch{}}
